#' @title Cast one temporal lifecycle column
#' @description
#' Cast persisted lifecycle values to the type generated by the current model
#' configuration builder.
#' @param current_column Vector read from persisted lifecycle state.
#' @param candidate_column Prototype vector from the candidate configuration.
#' @return Current values cast to the candidate column type.
#' @examples
#' cast_temporal_config_column(
#'   current_column = as.Date("2026-01-01"),
#'   candidate_column = NA_character_
#' )
cast_temporal_config_column <- function(
  current_column,
  candidate_column
) {
  if (
    is.character(candidate_column)
  ) {
    return(as.character(current_column))
  }

  if (
    is.integer(candidate_column)
  ) {
    return(as.integer(current_column))
  }

  if (
    is.double(candidate_column)
  ) {
    return(as.double(current_column))
  }

  if (
    is.logical(candidate_column)
  ) {
    return(as.logical(current_column))
  }

  if (
    inherits(candidate_column, "Date")
  ) {
    return(as.Date(current_column))
  }

  if (
    inherits(candidate_column, "POSIXct")
  ) {
    return(as.POSIXct(current_column, tz = "UTC"))
  }

  res_column <-
    vctrs::vec_cast(
      current_column,
      candidate_column
    )

  return(res_column)
}
